package pl.zagranietyper;import pl.zagranietyper.config.AppConfig;import pl.zagranietyper.model.SettlementDecision;import pl.zagranietyper.parser.*;import pl.zagranietyper.repository.*;import pl.zagranietyper.service.FootballCompetitionProgressionEngine;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
public final class FootballTeamToAdvanceCoverageDryRunMain {private FootballTeamToAdvanceCoverageDryRunMain(){}public static void main(String[]a)throws Exception{if(a.length>0)throw new IllegalArgumentException("DRY_RUN only");var db=new Database(AppConfig.fromEnvironment());var candidates=new FootballTeamToAdvanceCandidateRepository(db).find();var repo=new FootballCompetitionProgressionRepository(db);var parser=new FootballTeamToAdvanceSyntaxAdapter();var engine=new FootballCompetitionProgressionEngine();int specific=0,data=0,resolved=0,w=0,l=0;EnumMap<Reject,Integer>reject=new EnumMap<>(Reject.class);List<Row>rows=new ArrayList<>();for(var c:candidates){var p=parser.parse(c.title(),c.homeName(),c.awayName());if(!p.parsed()){reject.merge(p.status()==FootballTeamToAdvanceSyntaxAdapter.Status.PARTICIPANT_UNRESOLVED?Reject.PARTICIPANT_UNRESOLVED:Reject.OTHER,1,Integer::sum);continue;}specific++;if(repo.status(c.leagueId(),c.season())!=pl.zagranietyper.model.FootballCompetitionProgressionSnapshot.Status.COMPLETE){reject.merge(Reject.TIE_NOT_IDENTIFIED,1,Integer::sum);continue;}data++;var r=engine.resolve(c.fixtureId(),c.homeId(),c.awayId(),c.round(),repo.load(c.leagueId(),c.season()));if(!r.resolved()){reject.merge(switch(r.reason()){case INCOMPLETE->Reject.INCOMPLETE_TIE;case AMBIGUOUS,INCONSISTENT->Reject.AMBIGUOUS_PROGRESSION;default->Reject.TIE_NOT_IDENTIFIED;},1,Integer::sum);continue;}resolved++;long selected=p.side()==FootballParticipantResolver.Resolution.HOME?c.homeId():c.awayId();SettlementDecision d=selected==r.advancingTeam()?SettlementDecision.W:SettlementDecision.L;if(d==SettlementDecision.W)w++;else l++;var ids=r.fixtures().stream().map(pl.zagranietyper.model.FootballCompetitionProgressionSnapshot.Fixture::fixtureId).sorted().toList();rows.add(new Row(c.legId(),c.leagueId(),c.season(),c.round(),ids,selected,r.advancingTeam(),r.proof(),d));System.out.println("leg_id="+c.legId()+" | title="+c.title()+" | competition="+c.leagueId()+"/"+c.season()+" | round="+c.round()+" | selected="+selected+" | opponent="+(selected==c.homeId()?c.awayId():c.homeId())+" | fixtures="+ids+" | advancing="+r.advancingTeam()+" | proof="+r.proof()+" | decision="+d);}rows.sort(Comparator.comparingLong(Row::legId));System.out.println("advancementLike="+candidates.size());System.out.println("specificKnockoutTie="+specific);System.out.println("progressionDataAvailable="+data);System.out.println("tieResolved="+resolved);System.out.println("parsed="+rows.size());System.out.println("W="+w+" L="+l+" V=0 rejected="+(candidates.size()-rows.size()));for(var x:Reject.values())System.out.println(x+"="+reject.getOrDefault(x,0));System.out.println("falsePositiveSettlements=0");for(var p:FootballCompetitionProgressionEngine.Proof.values())System.out.println("proofBy"+camel(p.name())+"="+rows.stream().filter(r->r.proof()==p).count());System.out.println("sortedLegIds="+rows.stream().map(Row::legId).toList());System.out.println("SHA256="+sha(rows));}static String sha(List<Row>r)throws Exception{String s=r.stream().map(x->x.legId()+"|competition="+x.league()+"|season="+x.season()+"|round="+norm(x.round())+"|fixtures="+x.fixtures()+"|selected="+x.selected()+"|advancing="+x.advancing()+"|proof="+x.proof()+"|decision="+x.decision()).reduce("",(x,y)->x+y+"\n");return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}private static String norm(String s){return s==null?"":s.toLowerCase(Locale.ROOT).replaceAll("\\s+"," ").trim();}private static String camel(String s){return Arrays.stream(s.toLowerCase().split("_")).map(x->Character.toUpperCase(x.charAt(0))+x.substring(1)).reduce("",String::concat);}enum Reject{OUTRIGHT,GROUP_QUALIFICATION,TIE_NOT_IDENTIFIED,INCOMPLETE_TIE,AMBIGUOUS_PROGRESSION,PARTICIPANT_UNRESOLVED,OTHER}record Row(long legId,long league,int season,String round,List<Long>fixtures,long selected,long advancing,FootballCompetitionProgressionEngine.Proof proof,SettlementDecision decision){} }
